#include "staged_lm/pose_shape_forward.h"
#include <chrono>
#include <cmath>
namespace staged_lm { namespace { using Clock=std::chrono::steady_clock;double ms(Clock::time_point s){return std::chrono::duration<double,std::milli>(Clock::now()-s).count();}}
PoseShapeValueResult evaluate_pose_shape_value(const std::vector<float>& p,const std::vector<float>& basej,const std::vector<float>& jb,const std::vector<float>& anchor,const std::vector<float>& pose_anchor,float limit,float pose_scale,float shape_scale,float eps,float a2,float a4,const std::vector<std::int64_t>& parents,const PoseShapeCameraInput& i2,const PoseShapeCameraInput& i4){auto total=Clock::now();PoseShapeValueResult r;std::vector<float> z(p.begin()+75,p.end());r.shape=evaluate_shape_value(z,limit,basej,jb,55);r.cam2_dynamic_v_shaped=evaluate_dynamic_vertices(i2.selected_base_v_shaped,i2.selected_beta_shapedirs,r.shape.beta,i2.pose.point_count,&r.cam2_shape_ms);r.cam4_dynamic_v_shaped=evaluate_dynamic_vertices(i4.selected_base_v_shaped,i4.selected_beta_shapedirs,r.shape.beta,i4.pose.point_count,&r.cam4_shape_ms);PoseModelInput model{r.shape.joints,parents};auto c2=i2.pose;c2.parameters.assign(p.begin(),p.begin()+75);c2.selected_v_shaped=r.cam2_dynamic_v_shaped;auto c4=i4.pose;c4.parameters.assign(p.begin(),p.begin()+75);c4.selected_v_shaped=r.cam4_dynamic_v_shaped;r.cam2=evaluate_pose_camera_value(model,c2);r.cam4=evaluate_pose_camera_value(model,c4);auto os=Clock::now();const PoseCameraResult* cams[]={&r.cam2,&r.cam4};float alphas[]={a2,a4};float primary=0;for(int c=0;c<2;++c)for(size_t q=0;q<cams[c]->raw_residual.size()/2;++q){float u=cams[c]->raw_residual[2*q],v=cams[c]->raw_residual[2*q+1];float norm=std::sqrt(u*u+v*v);primary+=alphas[c]*(std::sqrt(norm*norm+eps*eps)-eps);}float ps=0,ss=0;for(size_t b=0;b<pose_anchor.size();++b){float x=(p[12+b]-pose_anchor[b])*pose_scale;ps+=x*x;}for(size_t b=0;b<anchor.size();++b){float x=(r.shape.beta[b]-anchor[b])*shape_scale;ss+=x*x;}r.objective_primary=primary;r.objective_pose_anchor=.5F*ps;r.objective_shape_anchor=.5F*ss;r.objective_total=static_cast<float>(r.objective_primary+r.objective_pose_anchor+r.objective_shape_anchor);r.objective_ms=ms(os);r.total_ms=ms(total);return r;}
}
